export function getCharacterTalentDetail(characterName: string): CharacterTalentDetail {
  if (!characterName) {
    return {
      talentBookName: 'Triết Học Của "Tự Do"',
      talentBookIcon: 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_104303.png',
      domainName: 'Hẻm Núi Forsaken (Mondstadt)',
      daysOfWeek: [1, 4, 0],
      weeklyBossMat: 'Nguyên Liệu Boss Tuần',
      weeklyBossMatIcon: 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_113055.png'
    };
  }

  const normalized = characterName
    .toLowerCase()
    .replace(/\s*\(.*?\)\s*/g, '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();

  if (CHARACTER_TALENTS[normalized]) {
    return CHARACTER_TALENTS[normalized];
  }

  for (const [k, detail] of Object.entries(CHARACTER_TALENTS)) {
    if (normalized.includes(k) || k.includes(normalized)) {
      return detail;
    }
  }

  return {
    talentBookName: 'Triết Học Của "Tự Do"',
    talentBookIcon: 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_104303.png',
    domainName: 'Hẻm Núi Forsaken (Mondstadt)',
    daysOfWeek: [1, 4, 0],
    weeklyBossMat: 'Nguyên Liệu Boss Tuần',
    weeklyBossMatIcon: 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_113055.png'
  };
}
